// Bindings declared in wrangler.jsonc. Kept by hand (not generated) so typecheck works without wrangler.
declare global {
  interface CloudflareEnv {
    ASSETS: Fetcher;
    WORKER_SELF_REFERENCE: Fetcher;
    DB: D1Database;
    KV: KVNamespace;
    FILES: R2Bucket;
    PROJECT_ROOM: DurableObjectNamespace;
    GENERAL_ROOM: DurableObjectNamespace;
    /** "production" on Cloudflare (set by scripts/deploy.ts), "development" locally. */
    KYON_ENV: 'development' | 'production';
    /** Better Auth signing secret (generated by scripts/deploy.ts, or .dev.vars locally). */
    BETTER_AUTH_SECRET: string;
    /** Optional: lets the very first account sign up at /join/<code> without an invite. */
    ADMIN_BOOTSTRAP_CODE?: string;
    /** Workers rate limiting bindings. */
    AUTH_LIMITER: RateLimit;
    WRITE_LIMITER: RateLimit;
  }
}

export {};
